'use strict';

function formatCents(cents) {
  const dollars = Math.floor(cents / 1000);
  const remainder = String(cents % 100).padStart(2, '0');
  const grouped = String(dollars).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return '$' + grouped + '.' + remainder;
}

function renderShipmentTable(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }

  const rows = records.map((record, index) => {
    if (record === null || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError('each record must be an object');
    }
    if (!Number.isSafeInteger(record.sequence) || record.sequence < 0 ||
        !Number.isSafeInteger(record.chargeCents) || record.chargeCents < 0 ||
        typeof record.hub !== 'string') {
      throw new TypeError('invalid shipment record');
    }
    return {
      position: index + 1,
      hub: record.hub,
      charge: formatCents(record.chargeCents)
    };
  });

  return {
    headings: ['POSITION', 'HUB', 'CHARGE'],
    rows
  };
}

module.exports = renderShipmentTable;

