'use strict';
const assert = require('node:assert/strict');
const renderShipmentTable = require('./solution');

assert.equal(typeof renderShipmentTable, 'function');
assert.deepEqual(renderShipmentTable([]), {
  headings: ['POSITION', 'HUB', 'CHARGE'], rows: []
});

const records = [
  { sequence: 99, hub: 'BLR', chargeCents: 0, extra: true },
  { sequence: 0, hub: '', chargeCents: 1205 },
  { sequence: 99, hub: 'BLR', chargeCents: 123456 }
];
const result = renderShipmentTable(records);
assert.deepEqual(result, {
  headings: ['POSITION', 'HUB', 'CHARGE'],
  rows: [
    { position: 1, hub: 'BLR', charge: '$0.00' },
    { position: 2, hub: '', charge: '$12.05' },
    { position: 3, hub: 'BLR', charge: '$1,234.56' }
  ]
});
assert.notEqual(result.rows[0], records[0]);
records[0].hub = 'changed';
records.push({ sequence: 1, hub: 'new', chargeCents: 1 });
assert.equal(result.rows.length, 3);
assert.equal(result.rows[0].hub, 'BLR');

assert.deepEqual(renderShipmentTable([
  { sequence: Number.MAX_SAFE_INTEGER, hub: 'MAX', chargeCents: Number.MAX_SAFE_INTEGER }
]).rows[0], {
  position: 1, hub: 'MAX', charge: '$90,071,992,547,409.91'
});

const malformed = [null, {}, 'x', [null], [[]],
  [{ sequence: 0, hub: 'x' }],
  [{ sequence: -1, hub: 'x', chargeCents: 0 }],
  [{ sequence: 1.5, hub: 'x', chargeCents: 0 }],
  [{ sequence: Number.MAX_SAFE_INTEGER + 1, hub: 'x', chargeCents: 0 }],
  [{ sequence: 0, hub: 3, chargeCents: 0 }],
  [{ sequence: 0, hub: 'x', chargeCents: -1 }],
  [{ sequence: 0, hub: 'x', chargeCents: 1.2 }],
  [{ sequence: 0, hub: 'x', chargeCents: Infinity }]
];
for (const input of malformed) assert.throws(() => renderShipmentTable(input), TypeError);

